package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact five API53 address cases admitted in Wave72; source and metadata unchanged.
func TestRunLeadAddressMappingContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLeadAddress53.cls"), "@IsTest private class GladeLeadAddress53 {\n private static void assertAddress(SObject row,String prefix,List<String> expected){\n  List<String> fields=new List<String>{'Street','City','State','PostalCode','Country'};\n  System.assertEquals(5,expected.size());\n  for(Integer i=0;i<fields.size();i++) System.assertEquals(expected[i],row.get(prefix+fields[i]),prefix+fields[i]);\n }\n private static void putAddress(SObject row,String prefix,List<String> values){\n  List<String> fields=new List<String>{'Street','City','State','PostalCode','Country'};\n  for(Integer i=0;i<fields.size();i++) row.put(prefix+fields[i],values[i]);\n }\n private static void checkConversion(Boolean existingAccount,Boolean existingContact,List<String> initial,List<String> leadAddress,List<String> expectedContact,List<String> expectedAccount){\n  Account account;\n  Contact contact;\n  if(existingAccount){account=new Account(Name='NativeLead Household');putAddress(account,'Billing',initial);insert account;}\n  if(existingContact){contact=new Contact(FirstName='Test',LastName='NativeLead',AccountId=account.Id);putAddress(contact,'Mailing',initial);insert contact;}\n  Lead leadToConvert=new Lead(FirstName='Test',LastName='NativeLead',Company='NativeLead Household');\n  putAddress(leadToConvert,'',leadAddress);insert leadToConvert;\n  Database.LeadConvert request=new Database.LeadConvert();request.setLeadId(leadToConvert.Id);\n  if(existingAccount) request.setAccountId(account.Id);\n  if(existingContact) request.setContactId(contact.Id);\n  LeadStatus converted=[SELECT ApiName FROM LeadStatus WHERE IsConverted=true LIMIT 1];request.setConvertedStatus(converted.ApiName);\n  Test.startTest();Database.LeadConvertResult result=Database.convertLead(request);Test.stopTest();\n  System.assertEquals(true,result.isSuccess());System.assertEquals(leadToConvert.Id,result.getLeadId());\n  if(existingAccount) System.assertEquals(account.Id,result.getAccountId());\n  if(existingContact) System.assertEquals(contact.Id,result.getContactId());\n  System.assertNotEquals(null,result.getOpportunityId());\n  Id contactId=result.getContactId();Id accountId=result.getAccountId();\n  Contact loadedContact=[SELECT AccountId,MailingStreet,MailingCity,MailingState,MailingPostalCode,MailingCountry FROM Contact WHERE Id=:contactId];\n  assertAddress(loadedContact,'Mailing',expectedContact);System.assertEquals(accountId,loadedContact.AccountId);\n  Account loadedAccount=[SELECT BillingStreet,BillingCity,BillingState,BillingPostalCode,BillingCountry FROM Account WHERE Id=:accountId];\n  assertAddress(loadedAccount,'Billing',expectedAccount);\n  Lead loadedLead=[SELECT Street,City,State,PostalCode,Country,IsConverted,ConvertedAccountId,ConvertedContactId,ConvertedOpportunityId FROM Lead WHERE Id=:leadToConvert.Id];\n  assertAddress(loadedLead,'',leadAddress);System.assertEquals(true,loadedLead.IsConverted);\n  System.assertEquals(accountId,loadedLead.ConvertedAccountId);System.assertEquals(contactId,loadedLead.ConvertedContactId);System.assertEquals(result.getOpportunityId(),loadedLead.ConvertedOpportunityId);\n  System.assertEquals(1,[SELECT count() FROM Contact]);System.assertEquals(1,[SELECT count() FROM Account]);\n }\n @IsTest static void existingBlankOriginalInputs(){\n  List<String> address=new List<String>{'123 Native Ld','Bellevue',null,'98005',null};\n  checkConversion(true,true,new List<String>{null,null,null,null,null},address,address,address);\n }\n @IsTest static void existingPopulatedAddress(){\n  List<String> owned=new List<String>{'456 Existing Rd','Seattle','Washington','98101','United States'};\n  List<String> lead=new List<String>{'123 Native Ld','Bellevue','Washington','98005','United States'};\n  checkConversion(true,true,owned,lead,owned,owned);\n }\n @IsTest static void existingPartialAddress(){\n  List<String> owned=new List<String>{'456 Existing Rd',null,null,'98101',null};\n  List<String> lead=new List<String>{'123 Native Ld','Bellevue','Washington','98005','United States'};\n  List<String> expected=new List<String>{'456 Existing Rd','Bellevue','Washington','98101','United States'};\n  checkConversion(true,true,owned,lead,expected,expected);\n }\n @IsTest static void newAccountAndContact(){\n  List<String> lead=new List<String>{'123 Native Ld','Bellevue','Washington','98005','United States'};\n  checkConversion(false,false,null,lead,lead,lead);\n }\n @IsTest static void existingAccountNewContact(){\n  List<String> owned=new List<String>{'456 Existing Rd','Seattle','Washington','98101','United States'};\n  List<String> lead=new List<String>{'123 Native Ld','Bellevue','Washington','98005','United States'};\n  checkConversion(true,false,owned,lead,lead,owned);\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeLeadAddress53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 5 || got.Passed != 5 || got.Skipped != 0 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("lead address contracts failed: %s", data)
	}
}
